'use client';

import { useCallback } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import {
  indexOfPhase,
  modelOf,
  PHASES,
  toolOf,
  WORKSPACE,
  type ModelId,
  type PhaseId,
  type ToolId,
} from './data';
import { FirstRun } from './first-run';
import { AgentStep, TeamStep, ToolsStep } from './phase-forms';
import { PhaseRow, type PhaseStatus } from './phase-row';
import { isRunDone, type Run } from './run';
import {
  CONNECT_MS,
  connectedToolsOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  TOTAL,
  type TextField,
  type WorkspaceAction,
  type WorkspaceState,
} from './session';
import { useRunClock } from './use-run-clock';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const LAST_INDEX = PHASES.length - 1;

function phaseStatusOf(index: number, currentIndex: number): PhaseStatus {
  if (index < currentIndex) {
    return 'done';
  }
  if (index === currentIndex) {
    return 'current';
  }
  return 'upcoming';
}

function hasRunEnded(run: Run | null) {
  if (!run) {
    return false;
  }
  return isRunDone(run);
}

function markerOf(status: PhaseStatus, isOver: boolean): PhaseStatus {
  if (isOver) {
    return 'done';
  }
  return status;
}

function doneCountOf(currentIndex: number, isLastStepOver: boolean) {
  if (isLastStepOver) {
    return currentIndex + 1;
  }
  return currentIndex;
}

function bodyIf(isCurrent: boolean, body: React.ReactNode) {
  if (isCurrent) {
    return body;
  }
  return null;
}

function continueLabelOf(phase: PhaseId) {
  if (phase === 'agent') {
    return 'Create agent';
  }
  return 'Continue';
}

/** Linear, Linear and GitHub, Notion, Linear and GitHub. */
function listOf(names: string[]) {
  if (names.length < 2) {
    return names.join('');
  }
  const head = names.slice(0, -1);
  const last = names[names.length - 1];
  return `${head.join(', ')} and ${last}`;
}

function peopleLineOf(count: number) {
  if (count === 1) {
    return '1 person invited';
  }
  return `${count} people invited`;
}

function summaryOf(phase: PhaseId, state: WorkspaceState) {
  if (phase === 'tools') {
    const connected = connectedToolsOf(state);
    const names = connected.map((id) => toolOf(id).name);
    return `${listOf(names)} connected`;
  }
  if (phase === 'team') {
    return peopleLineOf(state.invites.length);
  }
  if (phase === 'agent') {
    const model = modelOf(state.model).name;
    return `${state.agentName.trim()} on ${model}`;
  }
  return 'First job done';
}

export default function Onboarding03() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const tickRun = useCallback(() => act({ type: 'runTicked' }), [act]);
  useRunClock(state.run, isInView, tickRun);
  const { run } = state;
  const currentIndex = indexOfPhase(state.phase);
  const isWatching = state.phase === 'watch';
  const isRunOver = hasRunEnded(run);
  const isLastStepOver = isWatching && isRunOver;
  const doneCount = doneCountOf(currentIndex, isLastStepOver);
  const hasMoved = state.moves > 0;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /**
   * Works out where an action leads before it is sent: a step that changes takes the focus to its
   * heading, an entry that is refused takes it to what has to change.
   */
  function actAndFollow(action: WorkspaceAction) {
    const after = reducer(state, action);
    act(action);
    if (after.phase !== state.phase) {
      focusLater('[data-phase-heading]');
      return;
    }
    const wasRefused = after.attempts !== state.attempts;
    const refusal = after.hint;
    if (wasRefused && refusal) {
      focusLater(`[data-field="${refusal.field}"]`);
    }
  }

  /** The tool answers on its own a moment after the press, whoever pressed. */
  function connect(tool: ToolId) {
    act({ type: 'connectPressed', tool });
    schedule(() => act({ type: 'connected', tool }), CONNECT_MS);
  }

  /** The button that disconnects leaves with the connection, so the focus goes back to Connect. */
  function disconnect(tool: ToolId) {
    act({ type: 'disconnected', tool });
    focusLater(`[data-connect="${tool}"]`);
  }

  function typeText(field: TextField, value: string) {
    act({ type: 'typed', field, value });
  }

  function commitInvites() {
    actAndFollow({ type: 'inviteCommitted' });
  }

  /** The chip takes its button with it, so the focus goes back to the address box. */
  function removeInvite(address: string) {
    act({ type: 'inviteRemoved', address });
    focusLater('[data-field="invites"]');
  }

  function pickModel(model: ModelId) {
    act({ type: 'modelPicked', model });
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    actAndFollow({ type: 'continued' });
  }

  function edit(phase: PhaseId) {
    actAndFollow({ type: 'edited', phase });
  }

  /** Run again leaves with the result it sat in, so the focus goes to the heading of the step. */
  function runAgain() {
    act({ type: 'ranAgain' });
    focusLater('[data-phase-heading]');
  }

  /** A tool that is still connecting belongs to the round it was pressed in. */
  function replay() {
    clearAll();
    restart();
  }

  function currentBody() {
    if (isWatching) {
      if (!run) {
        return null;
      }
      return (
        <FirstRun
          run={run}
          agentName={state.agentName}
          model={state.model}
          onRunAgain={runAgain}
        />
      );
    }
    return (
      <form noValidate onSubmit={submit} className='flex flex-col gap-4'>
        {state.phase === 'tools' && (
          <ToolsStep
            tools={state.tools}
            hint={state.hint}
            attempts={state.attempts}
            pressed={pressed}
            onConnect={connect}
            onDisconnect={disconnect}
          />
        )}
        {state.phase === 'team' && (
          <TeamStep
            invites={state.invites}
            draft={state.inviteDraft}
            hint={state.hint}
            attempts={state.attempts}
            pressed={pressed}
            onType={typeText}
            onCommit={commitInvites}
            onRemove={removeInvite}
          />
        )}
        {state.phase === 'agent' && (
          <AgentStep
            agentName={state.agentName}
            model={state.model}
            job={state.job}
            hint={state.hint}
            attempts={state.attempts}
            onType={typeText}
            onPickModel={pickModel}
          />
        )}
        <div className='flex justify-end'>
          <Button
            type='submit'
            className={pressedSolidOf(pressed === 'continue')}
          >
            {continueLabelOf(state.phase)}
          </Button>
        </div>
      </form>
    );
  }

  const body = currentBody();

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container flex min-h-dvh w-full flex-col items-center p-4 @2xl:p-8'
      >
        <div className='flex w-full max-w-xl flex-col gap-5 @2xl:pt-4'>
          <header className='flex items-center gap-3'>
            <CompanyMark seed={WORKSPACE.name} size='lg' />
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='truncate text-lg font-semibold'>
                Set up {WORKSPACE.name}
              </h1>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
                <span className='flex items-baseline gap-1 tabular-nums'>
                  <MotionNumber value={doneCount} />
                  of {TOTAL} steps done
                </span>
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={replay}
              label='Replay'
            />
          </header>

          <section
            aria-label='Workspace setup'
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] @container rounded-xl px-4 py-2.5 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @md:px-5'
          >
            <ol aria-label='Setup steps' className='flex flex-col'>
              {PHASES.map((phase, index) => {
                const status = phaseStatusOf(index, currentIndex);
                const isCurrent = status === 'current';
                const isLast = index === LAST_INDEX;
                const showsEndedCheck = isLast && isLastStepOver;
                return (
                  <PhaseRow
                    key={phase.id}
                    phase={phase}
                    number={index + 1}
                    status={status}
                    marker={markerOf(status, showsEndedCheck)}
                    summary={summaryOf(phase.id, state)}
                    body={bodyIf(isCurrent, body)}
                    hasMoved={hasMoved}
                    onEdit={edit}
                  />
                );
              })}
            </ol>
          </section>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import type { Phase, PhaseId } from './data';

export type PhaseStatus = 'done' | 'current' | 'upcoming';

const NUMBER =
  'inline-flex size-[18px] items-center justify-center rounded-full text-[11px] leading-none font-medium tabular-nums';

const STATUS_WORD: Record<PhaseStatus, string> = {
  done: 'Done',
  current: 'Current step',
  upcoming: 'Upcoming',
};

/** A summary that arrives after the first move fades in. Nothing fades when the page loads. */
function arrivalOf(hasMoved: boolean) {
  if (hasMoved) {
    return 'transition-opacity duration-300 starting:opacity-0';
  }
  return undefined;
}

type MarkerProps = {
  status: PhaseStatus;
  number: number;
};

/** The number turns into a check that draws itself when its step is done. A step done when the page loads shows its check at once. */
function Marker({ status, number }: MarkerProps) {
  return (
    <Swap swapKey={status} className='size-[18px] shrink-0 justify-center'>
      {status === 'done' && (
        <DrawnCheck tone='success' entrance='draw' pace='calm' />
      )}
      {status === 'current' && (
        <span className={cn(NUMBER, 'bg-primary text-primary-foreground')}>
          {number}
        </span>
      )}
      {status === 'upcoming' && (
        <span
          className={cn(NUMBER, 'bg-foreground/[0.06] text-muted-foreground')}
        >
          {number}
        </span>
      )}
    </Swap>
  );
}

export type PhaseRowProps = {
  phase: Phase;
  number: number;
  status: PhaseStatus;
  /** The mark beside the step. The last step stays open on its result and shows its check once its run is over. */
  marker: PhaseStatus;
  /** What a step that is done left behind, said in one line. */
  summary: string;
  /** What the step asks for, while it is the current one. */
  body: React.ReactNode;
  /** True once the session moved between steps at least once. */
  hasMoved: boolean;
  onEdit: (phase: PhaseId) => void;
};

/**
 * One step of the setup. Done, it folds into a single line that says what it left behind, with the
 * way back to it; current, it opens under its heading; upcoming, it waits in the faint ink.
 */
export function PhaseRow({
  phase,
  number,
  status,
  marker,
  summary,
  body,
  hasMoved,
  onEdit,
}: PhaseRowProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const isDone = status === 'done';
  const isCurrent = status === 'current';
  const isUpcoming = status === 'upcoming';

  return (
    <li className='flex flex-col'>
      <div className='flex min-h-10 items-center gap-3'>
        <Marker status={marker} number={number} />
        {isDone && (
          <p
            className={cn(
              'flex min-w-0 flex-1 items-baseline gap-2',
              arrivalOf(hasMoved)
            )}
          >
            <span className='text-muted-foreground shrink-0 text-xs'>
              <span className='sr-only'>{STATUS_WORD.done}: </span>
              {phase.label}
            </span>
            <span className='min-w-0 truncate text-[13px]'>{summary}</span>
          </p>
        )}
        {isCurrent && (
          <h2
            data-phase-heading
            tabIndex={-1}
            className='focus-visible:ring-ring/25 min-w-0 flex-1 rounded-sm text-sm font-medium text-balance outline-none focus-visible:ring-[3px]'
          >
            <span className='sr-only'>{STATUS_WORD.current}: </span>
            {phase.title}
          </h2>
        )}
        {isUpcoming && (
          <p className='text-muted-foreground min-w-0 flex-1 truncate text-[13px]'>
            <span className='sr-only'>{STATUS_WORD.upcoming}: </span>
            {phase.title}
          </p>
        )}
        {isDone && (
          <Button
            type='button'
            variant='ghost'
            size='sm'
            aria-label={`Edit ${phase.label}`}
            onClick={() => onEdit(phase.id)}
            className='text-muted-foreground -me-1.5 shrink-0'
          >
            Edit
          </Button>
        )}
      </div>
      <AnimatePresence initial={false}>
        {isCurrent && (
          <motion.div
            key='body'
            className='-mx-1 overflow-hidden px-1'
            {...presence}
          >
            <div className='flex flex-col gap-4 pt-0.5 pb-4 @md:ps-[1.875rem]'>
              <p className='text-muted-foreground text-xs leading-5 text-pretty'>
                {phase.lead}
              </p>
              {body}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </li>
  );
}

'use client';

import { useId } from 'react';

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { MailIcon, PlugIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import { Label, LABEL_RECIPE } from '@/registry/ndeko/ui/label';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';

import {
  AGENT_SEED,
  AGENT_SERIES,
  JOB_MAX_LENGTH,
  MODELS,
  TOOLS,
  type ModelId,
  type Tool,
  type ToolId,
} from './data';
import { ENDS_AN_ADDRESS } from './invites';
import type { ConnectStatus, Hint, HintField, TextField } from './session';

const CONNECT_STATE: Record<ConnectStatus, MorphState> = {
  idle: 'idle',
  connecting: 'busy',
  connected: 'done',
};

const CONNECT_LABELS: Record<MorphState, string> = {
  idle: 'Connect',
  busy: 'Connecting',
  done: 'Connected',
};

/** A tray inside the card. A connected tool takes the tint of what went well. */
const TOOL_ROW =
  'flex items-center gap-3 rounded-lg p-2.5 transition-colors duration-200';

/** A tray inside the card, tinted when its model is the one picked. The whole tray answers the press. */
const MODEL_CHOICE =
  'bg-foreground/[0.04] has-data-checked:bg-primary/[0.08] relative flex items-center gap-3 rounded-lg p-3 transition-colors duration-150';

/** Someone invited has not joined yet: a dashed slot with an envelope, since nobody is there. */
const INVITED =
  'hairline-border border-foreground/25 flex h-7 max-w-full items-center gap-1.5 rounded-full border-dashed ps-2.5 pe-0.5 text-xs transition-opacity duration-200 starting:opacity-0';

const REMOVE =
  'focus-visible:ring-ring/25 hover:bg-foreground/[0.08] text-muted-foreground hover:text-foreground flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full transition-colors duration-150 outline-none focus-visible:ring-[3px]';

const LONE_HINT =
  'text-destructive-ink text-xs transition-[opacity,translate] duration-200 ease-(--ease-out-strong) starting:-translate-y-0.5 starting:opacity-0';

/** The hint of one field, when the last refusal was about it. */
function hintFor(hint: Hint | null, field: HintField) {
  if (hint?.field === field) {
    return hint;
  }
  return null;
}

function describedByOf(hint: Hint | null, hintId: string) {
  if (hint) {
    return hintId;
  }
  return undefined;
}

function toolToneOf(isConnected: boolean) {
  if (isConnected) {
    return 'bg-success/[0.08]';
  }
  return 'bg-foreground/[0.04]';
}

/** Connect Notion, Connecting Notion, Notion connected: the name says which tool the button is for. */
function connectLabelOf(status: ConnectStatus, name: string) {
  if (status === 'connected') {
    return `${name} connected`;
  }
  const morph = CONNECT_STATE[status];
  const word = CONNECT_LABELS[morph];
  return `${word} ${name}`;
}

/** The first tool takes the focus when Continue finds nothing connected, and says the hint. */
function fieldMarkOf(isFirst: boolean) {
  if (isFirst) {
    return 'tools';
  }
  return undefined;
}

function firstOnlyOf(isFirst: boolean, id: string | undefined) {
  if (isFirst) {
    return id;
  }
  return undefined;
}

type ToolRowProps = {
  tool: Tool;
  status: ConnectStatus;
  isFirst: boolean;
  /** The id of the hint of the step, while it shows. */
  shownHintId: string | undefined;
  isPressed: boolean;
  onConnect: (tool: ToolId) => void;
  onDisconnect: (tool: ToolId) => void;
};

function ToolRow({
  tool,
  status,
  isFirst,
  shownHintId,
  isPressed,
  onConnect,
  onDisconnect,
}: ToolRowProps) {
  const isConnected = status === 'connected';
  const describedBy = firstOnlyOf(isFirst, shownHintId);

  return (
    <li className={cn(TOOL_ROW, toolToneOf(isConnected))}>
      <BrandTile brand={tool.brand} size='lg' />
      <div className='flex min-w-0 flex-1 flex-col'>
        <p className='truncate text-[13px] font-medium'>{tool.name}</p>
        <p className='text-muted-foreground truncate text-xs'>{tool.shares}</p>
      </div>
      <MorphButton
        type='button'
        size='sm'
        variant='outline'
        data-connect={tool.id}
        data-field={fieldMarkOf(isFirst)}
        aria-label={connectLabelOf(status, tool.name)}
        aria-describedby={describedBy}
        state={CONNECT_STATE[status]}
        labels={CONNECT_LABELS}
        idleIcon={<PlugIcon />}
        onClick={() => onConnect(tool.id)}
        className={pressedQuietOf(isPressed)}
      />
      <span className='flex size-7 shrink-0 items-center justify-center'>
        {isConnected && (
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            aria-label={`Disconnect ${tool.name}`}
            onClick={() => onDisconnect(tool.id)}
            className='text-muted-foreground transition-[opacity,color,background-color,scale] duration-200 starting:opacity-0'
          >
            <XIcon />
          </Button>
        )}
      </span>
    </li>
  );
}

export type ToolsStepProps = {
  tools: Record<ToolId, ConnectStatus>;
  hint: Hint | null;
  /** Counts the refused entries: a hint that comes back after a new try arrives again. */
  attempts: number;
  pressed: string | null;
  onConnect: (tool: ToolId) => void;
  onDisconnect: (tool: ToolId) => void;
};

export function ToolsStep({
  tools,
  hint,
  attempts,
  pressed,
  onConnect,
  onDisconnect,
}: ToolsStepProps) {
  const hintId = useId();
  const toolsHint = hintFor(hint, 'tools');
  const shownHintId = describedByOf(toolsHint, hintId);

  return (
    <div className='flex flex-col gap-2'>
      <ul aria-label='Tools' className='flex flex-col gap-1.5'>
        {TOOLS.map((tool, index) => (
          <ToolRow
            key={tool.id}
            tool={tool}
            status={tools[tool.id]}
            isFirst={index === 0}
            shownHintId={shownHintId}
            isPressed={pressed === `connect-${tool.id}`}
            onConnect={onConnect}
            onDisconnect={onDisconnect}
          />
        ))}
      </ul>
      {toolsHint && (
        <p key={attempts} id={hintId} className={LONE_HINT}>
          {toolsHint.message}
        </p>
      )}
    </div>
  );
}

export type TeamStepProps = {
  invites: string[];
  draft: string;
  hint: Hint | null;
  attempts: number;
  pressed: string | null;
  onType: (field: TextField, value: string) => void;
  onCommit: () => void;
  onRemove: (address: string) => void;
};

export function TeamStep({
  invites,
  draft,
  hint,
  attempts,
  pressed,
  onType,
  onCommit,
  onRemove,
}: TeamStepProps) {
  const invitesHint = hintFor(hint, 'invites');
  const hasInvites = invites.length > 0;

  function typeAddress(value: string) {
    onType('inviteDraft', value);
    if (ENDS_AN_ADDRESS.test(value)) {
      onCommit();
    }
  }

  /** Enter adds what the box holds. On an empty box it is left alone, and the step goes on. */
  function addOnEnter(event: React.KeyboardEvent<HTMLInputElement>) {
    const isBoxEmpty = draft.trim() === '';
    if (event.key !== 'Enter' || isBoxEmpty) {
      return;
    }
    event.preventDefault();
    onCommit();
  }

  return (
    <div className='flex flex-col gap-3'>
      <Field invalid={Boolean(invitesHint)}>
        <FieldLabel>Email addresses</FieldLabel>
        <div className='flex items-center gap-2'>
          <Input
            data-field='invites'
            inputMode='email'
            autoComplete='off'
            autoCapitalize='none'
            spellCheck={false}
            placeholder='name@company.com'
            value={draft}
            onChange={(event) => typeAddress(event.target.value)}
            onKeyDown={addOnEnter}
          />
          <Button
            type='button'
            variant='outline'
            onClick={onCommit}
            className={cn('shrink-0', pressedQuietOf(pressed === 'add-invite'))}
          >
            Add
          </Button>
        </div>
        {invitesHint && (
          <FieldError key={attempts} match>
            {invitesHint.message}
          </FieldError>
        )}
        {!invitesHint && (
          <FieldDescription>
            Press Enter after each address, or paste several at once
          </FieldDescription>
        )}
      </Field>
      <div className='flex min-h-7 items-center'>
        {!hasInvites && (
          <p className='text-muted-foreground text-xs'>Nobody is invited yet</p>
        )}
