'use client';

import { useEffect, useRef } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';

import { isRunDone, TICK_DELAYS_MS, type Run } from './run';

type Pending = {
  key: string;
  remaining: number;
  scheduledAt: number;
};

/** A run and the moment it waits for: a new run or a new moment starts a new wait. */
function waitKeyOf(run: Run | null) {
  if (!run) {
    return '';
  }
  return `${run.startedAt}:${run.tick}`;
}

function delayOf(run: Run | null) {
  if (!run) {
    return 0;
  }
  return TICK_DELAYS_MS[run.tick] ?? 0;
}

function hasMomentsLeft(run: Run | null) {
  if (!run) {
    return false;
  }
  return !isRunDone(run);
}

function remainingOf(saved: Pending | null, key: string, delay: number) {
  if (saved?.key === key) {
    return saved.remaining;
  }
  return delay;
}

/**
 * Plays a first run one moment at a time, for the demonstration and for a person alike: it asks for
 * the next moment once the one before had its time. Off screen and in a hidden tab it keeps what
 * was left of the wait, so a run never moves while nobody looks.
 */
export function useRunClock(
  run: Run | null,
  isOnScreen: boolean,
  onTick: () => void
) {
  const isVisible = useDocumentVisible();
  const pending = useRef<Pending | null>(null);
  const key = waitKeyOf(run);
  const delay = delayOf(run);
  const isDue = hasMomentsLeft(run);
  const isPlaying = isOnScreen && isVisible && isDue;

  useEffect(() => {
    if (!isPlaying) {
      return;
    }
    const remaining = remainingOf(pending.current, key, delay);
    pending.current = { key, remaining, scheduledAt: Date.now() };
    const timer = setTimeout(() => {
      pending.current = null;
      onTick();
    }, remaining);
    return () => {
      clearTimeout(timer);
      const saved = pending.current;
      if (!saved) {
        return;
      }
      const spent = Date.now() - saved.scheduledAt;
      const left = Math.max(0, saved.remaining - spent);
      pending.current = { ...saved, remaining: left };
    };
  }, [isPlaying, key, delay, onTick]);
}

import type {
  CallStatus,
  PlanStep,
  StepStatus,
  ToolCall,
} from '@/registry/ndeko/lib/agent-run';

import { toolOf, type Tool, type ToolId, type ToolTask } from './data';

/**
 * A first run as a short film of five moments. A moment starts or ends a step of the plan or a
 * call to a tool; what is on screen is worked out from how many moments have passed and when.
 */
export type Run = {
  /** The tools the run works with: the first two that are connected. */
  tools: ToolId[];
  startedAt: number;
  /** How many moments the run has been through. */
  tick: number;
  /** When each moment happened. */
  stamps: number[];
};

export const RUN_TICKS = 5;

/** The wait before each moment, the first one included. */
export const TICK_DELAYS_MS = [700, 1100, 1500, 1400, 1600];

function sumOf(values: number[]) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

export const RUN_MS = sumOf(TICK_DELAYS_MS);

/** The moment something starts at and the moment it ends at. */
type Span = {
  from: number;
  to: number;
};

const PLAN_SPANS: Span[] = [
  { from: 1, to: 2 },
  { from: 2, to: 4 },
  { from: 4, to: 5 },
];

const CALL_SPANS: Span[] = [
  { from: 2, to: 3 },
  { from: 3, to: 4 },
];

export function newRun(tools: ToolId[], now: number): Run {
  return { tools, startedAt: now, tick: 0, stamps: [] };
}

export function isRunDone(run: Run) {
  return run.tick >= RUN_TICKS;
}

export function tickedRun(run: Run, now: number): Run {
  if (isRunDone(run)) {
    return run;
  }
  return { ...run, tick: run.tick + 1, stamps: [...run.stamps, now] };
}

function hasReached(run: Run, moment: number) {
  return run.tick >= moment;
}

function stepStatusOf(run: Run, span: Span): StepStatus {
  if (hasReached(run, span.to)) {
    return 'done';
  }
  if (hasReached(run, span.from)) {
    return 'running';
  }
  return 'upcoming';
}

function callStatusOf(run: Run, span: Span): CallStatus {
  if (hasReached(run, span.to)) {
    return 'done';
  }
  if (hasReached(run, span.from)) {
    return 'running';
  }
  return 'queued';
}

/** Moments are counted from one, their times are kept from zero. A moment not reached yet has no time. */
function timesOf(run: Run, span: Span) {
  return {
    startedAt: run.stamps[span.from - 1],
    endedAt: run.stamps[span.to - 1],
  };
}

export type RunTask = {
  tool: Tool;
  task: ToolTask;
};

/** Two things to do: one in each of two tools, or two in the same one when it is the only one. */
export function tasksOf(tools: ToolId[]): RunTask[] {
  const [firstId, secondId] = tools;
  if (firstId === undefined) {
    return [];
  }
  const first = toolOf(firstId);
  if (secondId === undefined) {
    return [
      { tool: first, task: first.tasks[0] },
      { tool: first, task: first.tasks[1] },
    ];
  }
  const second = toolOf(secondId);
  return [
    { tool: first, task: first.tasks[0] },
    { tool: second, task: second.tasks[0] },
  ];
}

/** Linear and GitHub, or Linear when both tasks are in it. */
export function toolNamesOf(tools: ToolId[]) {
  const names = tools.map((id) => toolOf(id).name);
  return names.join(' and ');
}

const PLAN_IDS = ['read', 'gather', 'write'];

function planTitlesOf(run: Run) {
  return [
    'Read the job',
    `Gather from ${toolNamesOf(run.tools)}`,
    'Write the summary',
  ];
}

export function planOf(run: Run): PlanStep[] {
  const titles = planTitlesOf(run);
  return PLAN_SPANS.map((span, index) => ({
    id: PLAN_IDS[index],
    title: titles[index],
    status: stepStatusOf(run, span),
    ...timesOf(run, span),
  }));
}

export function callsOf(run: Run): ToolCall[] {
  const tasks = tasksOf(run.tools);
  return tasks.map((entry, index) => {
    const span = CALL_SPANS[index];
    return {
      id: `call-${index}`,
      tool: entry.tool.id,
      label: entry.task.label,
      status: callStatusOf(run, span),
      output: entry.task.finding,
      ...timesOf(run, span),
    };
  });
}

/** What the agent hands back: where it looked, then what it found there. */
export function resultOf(run: Run) {
  const tasks = tasksOf(run.tools);
  const findings = tasks.map((entry) => `${entry.task.finding}.`);
  const sentences = [`Looked at ${toolNamesOf(run.tools)}.`, ...findings];
  return sentences.join(' ');
}

/** The run from its start to its last moment, for the clock that times it. */
export function runTimesOf(run: Run) {
  return {
    startedAt: run.startedAt,
    endedAt: run.stamps[RUN_TICKS - 1],
  };
}

const SEPARATORS = /[\s,;]+/;

/** A space, a comma or a semicolon ends an address as it is typed. */
export const ENDS_AN_ADDRESS = /[\s,;]$/;

/**
 * One @ with something before it, and a dot inside what follows. Read by hand, piece by piece,
 * so a long pasted text can never make the check slow.
 */
function isEmail(text: string) {
  const at = text.indexOf('@');
  const hasOneAt = at > 0 && at === text.lastIndexOf('@');
  if (!hasOneAt) {
    return false;
  }
  const domain = text.slice(at + 1);
  const dot = domain.lastIndexOf('.');
  const lastPlace = domain.length - 1;
  return dot > 0 && dot < lastPlace;
}

export type Committed = {
  invites: string[];
  /** What could not be read as an address stays in the box. */
  draft: string;
  error?: string;
};

function notAnAddressLineOf(rejected: string[]) {
  const [first] = rejected;
  if (rejected.length === 1) {
    return `${first} is not an email address`;
  }
  return `${first} and ${rejected.length - 1} more are not email addresses`;
}

/**
 * Turns what the address box holds into addresses: several can be pasted at once, separated by
 * spaces, commas or semicolons. One that is already invited is not added twice.
 */
export function committedInvites(current: string[], draft: string): Committed {
  const pieces = draft.split(SEPARATORS);
  const typed = pieces.filter((piece) => piece !== '');
  const invites = [...current];
  const rejected: string[] = [];
  for (const piece of typed) {
    const address = piece.toLowerCase();
    if (!isEmail(address)) {
      rejected.push(piece);
      continue;
    }
    if (!invites.includes(address)) {
      invites.push(address);
    }
  }
  if (rejected.length === 0) {
    return { invites, draft: '' };
  }
  return {
    invites,
    draft: rejected.join(' '),
    error: notAnAddressLineOf(rejected),
  };
}

